// Gmail Trigger with downloadAttachments=true names binary props
// attachment_0, attachment_1, ... (not 'data'). Find the first one,
// derive mime + filename + extract `op`, and rename to 'data' so the
// downstream Extract node (binaryPropertyName='data') works.
// We reach back to the Gmail Trigger directly rather than relying on
// $input because the upstream Set node strips binary in some configs.
const triggerItem = $('A_Gmail Trigger Docs').first();
const item = $input.first();
const binary = (triggerItem && triggerItem.binary) || item.binary || {};
const keys = Object.keys(binary);
if (keys.length === 0) {
  throw new Error('No binary attachment on item. Check Gmail Trigger \u2192 Options \u2192 Download Attachments is ON, and that the email actually has an attachment.');
}
// Prefer a key whose mimeType is a recognisable document type; fall
// back to the first key otherwise.
const docLike = (k) => {
  const m = (binary[k].mimeType || '').toLowerCase();
  return m.includes('pdf') || m.includes('word') || m.includes('spreadsheet') || m.includes('csv') || m.includes('text');
};
const chosenKey = keys.find(docLike) || keys[0];
const bin = binary[chosenKey];

const mime = (bin.mimeType || '').toLowerCase();
const fileName = bin.fileName || '';
const ext = (fileName.split('.').pop() || '').toLowerCase();

let op = 'text';
if (mime.includes('pdf') || ext === 'pdf') op = 'pdf';
else if (mime.includes('spreadsheet') || ['xlsx','xls'].includes(ext)) op = 'xlsx';
else if (mime.includes('csv') || ext === 'csv') op = 'csv';
else if (mime.includes('word') || ['docx','doc'].includes(ext)) {
  throw new Error('DOCX/DOC not supported by extractFromFile. Convert to PDF upstream. File: ' + fileName);
}

return [{
  json: {
    ...item.json,
    op,
    mime_effective: mime,
    title: fileName || item.json.email_subject || 'untitled',
    attachment_key: chosenKey,
  },
  binary: { data: bin },
}];

// Pure-JS SHA-256 — n8n Code node sandbox blocks both `require('crypto')`
// AND the Web Crypto API global. Self-contained, no deps.
function sha256(msg){
  const utf8=[];for(let i=0;i<msg.length;i++){let c=msg.charCodeAt(i);if(c<0x80)utf8.push(c);else if(c<0x800){utf8.push(0xc0|(c>>6),0x80|(c&0x3f));}else if(c<0xd800||c>=0xe000){utf8.push(0xe0|(c>>12),0x80|((c>>6)&0x3f),0x80|(c&0x3f));}else{i++;c=0x10000+(((c&0x3ff)<<10)|(msg.charCodeAt(i)&0x3ff));utf8.push(0xf0|(c>>18),0x80|((c>>12)&0x3f),0x80|((c>>6)&0x3f),0x80|(c&0x3f));}}
  const bitLen=utf8.length*8;utf8.push(0x80);
  while((utf8.length%64)!==56)utf8.push(0);
  utf8.push(0,0,0,0,(bitLen>>>24)&0xff,(bitLen>>>16)&0xff,(bitLen>>>8)&0xff,bitLen&0xff);
  const h=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];
  const k=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];
  for(let i=0;i<utf8.length;i+=64){
    const w=new Array(64);
    for(let t=0;t<16;t++)w[t]=(utf8[i+t*4]<<24)|(utf8[i+t*4+1]<<16)|(utf8[i+t*4+2]<<8)|utf8[i+t*4+3];
    for(let t=16;t<64;t++){
      const s0=((w[t-15]>>>7)|(w[t-15]<<25))^((w[t-15]>>>18)|(w[t-15]<<14))^(w[t-15]>>>3);
      const s1=((w[t-2]>>>17)|(w[t-2]<<15))^((w[t-2]>>>19)|(w[t-2]<<13))^(w[t-2]>>>10);
      w[t]=(w[t-16]+s0+w[t-7]+s1)|0;
    }
    let a=h[0],b=h[1],c=h[2],d=h[3],e=h[4],f=h[5],g=h[6],hh=h[7];
    for(let t=0;t<64;t++){
      const S1=((e>>>6)|(e<<26))^((e>>>11)|(e<<21))^((e>>>25)|(e<<7));
      const ch=(e&f)^(~e&g);
      const t1=(hh+S1+ch+k[t]+w[t])|0;
      const S0=((a>>>2)|(a<<30))^((a>>>13)|(a<<19))^((a>>>22)|(a<<10));
      const mj=(a&b)^(a&c)^(b&c);
      const t2=(S0+mj)|0;
      hh=g;g=f;f=e;e=(d+t1)|0;d=c;c=b;b=a;a=(t1+t2)|0;
    }
    h[0]=(h[0]+a)|0;h[1]=(h[1]+b)|0;h[2]=(h[2]+c)|0;h[3]=(h[3]+d)|0;
    h[4]=(h[4]+e)|0;h[5]=(h[5]+f)|0;h[6]=(h[6]+g)|0;h[7]=(h[7]+hh)|0;
  }
  return h.map(n=>(n>>>0).toString(16).padStart(8,'0')).join('');
}

const item = $input.first().json;
// extractFromFile outputs differ per op; coalesce to a single text blob.
let text = '';
if (typeof item.text === 'string') text = item.text;
else if (Array.isArray(item.data)) text = JSON.stringify(item.data);
else if (item.content) text = String(item.content);
else text = JSON.stringify(item);

const hash = sha256(text);

