const upstream = $('A_MIME Router').first().json;
const word_count = text.trim().split(/\s+/).filter(Boolean).length;
return [{ json: { ...upstream, body_text: text, body_hash: hash, word_count } }];

const src = $('A_Hash & Wordcount').first().json;
const MAX = 25000;
let body = src.body_text;
if (src.word_count > MAX) {
  // crude truncation — v2 will chunk+reduce
  const words = body.split(/\s+/);
  body = words.slice(0, MAX).join(' ') + '\n\n[truncated: original was ' + src.word_count + ' words]';
}
return [{ json: { ...src, body_text_for_llm: body } }];

const raw = $input.first().json.output || $input.first().json.text || '';
function strip(s){return s.replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();}
function repair(s){return s.replace(/,\s*([}\]])/g,'$1').replace(/[\u201C\u201D]/g,'"').replace(/[\u2018\u2019]/g,"'" );}
let parsed;
try { parsed = JSON.parse(raw); }
catch { try { parsed = JSON.parse(strip(raw)); } catch { try { parsed = JSON.parse(repair(strip(raw))); } catch (e) {
  const m = raw.match(/{[\s\S]*}/); if (m) parsed = JSON.parse(repair(m[0])); else throw e;
}}}
