  safe_mime: esc(row.mime_effective || row.mime_hint),
  safe_body: esc(row.body_text),
  safe_body_hash: esc(row.body_hash),
  safe_brief: esc(row.executive_brief),
  safe_key_facts: esc(JSON.stringify(row.key_facts || [])),
  safe_action_items: esc(JSON.stringify(row.action_items || [])),
  safe_deadlines: esc(JSON.stringify(row.deadlines || [])),
  risk_score: row.risk_score ?? 0,
  safe_routing: esc(row.suggested_routing || 'other'),
  embedding_literal: '[' + emb.join(',') + ']',
