const raw = $input.first().json.output || $input.first().json.text || '';
function strip(s){return s.replace(/^```(?:json)?/i,'').replace(/```$/,'').trim();}
function repair(s){return s.replace(/,\s*([}\]])/g,'$1').replace(/[\u201C\u201D]/g,'"');}
let parsed;
try { parsed = JSON.parse(raw); } catch {
  try { parsed = JSON.parse(strip(raw)); } catch {
    try { parsed = JSON.parse(repair(strip(raw))); } catch(e) {
