}
const up = $('B_Parse Parties').first().json;
const usage = ($input.first().json.tokenUsage) || {};
// Subject precedence: LLM's own subject → parties+type composition → filename-minus-extension.
const partiesStr = Array.isArray(up.parties) && up.parties.length ? up.parties.join(' \u00d7 ') : '';
const composed = [up.contract_type, partiesStr].filter(Boolean).join(' \u2014 ');
const filenameFallback = (up.title || 'Untitled contract').replace(/\.[a-z0-9]+$/i, '');
return [{ json: {
