const contractRow = $input.first().json; // {id} from INSERT RETURNING
const parsed = $('B_Parse Clauses JSON').first().json;
// pairedItem is REQUIRED on array-fan-out outputs so downstream nodes
// (especially Code in per-item mode) can resolve .item references.
const out = (parsed.clauses || []).map((c, i) => ({
  json: {
    contract_id: contractRow.id,
    seq: i,
    category: c.category,
    clause_text: c.clause_text || '',
    page_ref: c.page_ref || null,
    risk_level: (c.risk_level || 'low').toLowerCase(),
    rationale: c.rationale || ''
  },
  pairedItem: { item: 0 },
}));
return out;

const esc = (s) => String(s == null ? '' : s).replace(/'/g, "''");
const embResponses = $input.all();
const clauses = $('B_Split Clauses').all();
if (embResponses.length !== clauses.length) {
  throw new Error(`Item count mismatch: ${embResponses.length} embeddings vs ${clauses.length} clauses — order cannot be zipped reliably.`);
}
const out = embResponses.map((e, i) => {
  const r = e.json;
  if (!r || !r.data || !r.data[0] || !r.data[0].embedding) {
    throw new Error(`No embedding on item ${i} (OpenAI may have errored/rate-limited).`);
  }
  const emb = r.data[0].embedding;
  const clause = clauses[i].json;
  return { json: {
    contract_id: clause.contract_id,
    safe_category: esc(clause.category || 'Other'),
    safe_clause_text: esc(clause.clause_text || ''),
    page_ref_sql: clause.page_ref ? "'" + esc(clause.page_ref) + "'" : 'NULL',
    safe_risk_level: esc(clause.risk_level || 'low'),
    safe_rationale: esc(clause.rationale || ''),
    embedding_literal: '[' + emb.join(',') + ']'
  }};
});
return out;

