function toTelegramHtml(s) {
  if (!s) return '';
  let t = s;
  t = t.replace(/<br\s*\/?>/gi, '\n');
  t = t.replace(/<\/?(strong|b)>/gi, m => m.startsWith('</') ? '\u0001BCLOSE\u0001' : '\u0001BOPEN\u0001');
  t = t.replace(/<\/?(em|i)>/gi, m => m.startsWith('</') ? '\u0001ICLOSE\u0001' : '\u0001IOPEN\u0001');
  t = t.replace(/<\/?(code|pre)>/gi, m => m.startsWith('</') ? '\u0001CCLOSE\u0001' : '\u0001COPEN\u0001');
  t = t.replace(/<\/?(p|div|h[1-6]|ul|ol|li|span)[^>]*>/gi, '');
  t = t.replace(/<[^>]+>/g, '');
  t = t.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  t = t.replace(/\u0001BOPEN\u0001/g, '<b>').replace(/\u0001BCLOSE\u0001/g, '</b>');
  t = t.replace(/\u0001IOPEN\u0001/g, '<i>').replace(/\u0001ICLOSE\u0001/g, '</i>');
  t = t.replace(/\u0001COPEN\u0001/g, '<code>').replace(/\u0001CCLOSE\u0001/g, '</code>');
  t = t.replace(/\*\*([^*\n]+?)\*\*/g, '<b>$1</b>');
  t = t.replace(/(^|[^*\w])\*(?!\s)([^*\n]{1,200}?)(?<!\s)\*(?!\w)/g, '$1<i>$2</i>');
  t = t.replace(/`([^`\n]+)`/g, '<code>$1</code>');
  t = t.replace(/^[ \t]*[*-][ \t]+/gm, '\u2022 ');
  t = t.replace(/^#{1,6}[ \t]*/gm, '');
  return t;
}

// Strip all of an imbalanced tag type so Telegram's HTML parser doesn't
// reject the whole message. Applied per-chunk (after splitting) because
// a chunk boundary may land inside a tag pair.
function balanceTags(s) {
  for (const tag of ['b', 'i', 'code']) {
    const open  = (s.match(new RegExp('<' + tag + '>', 'g')) || []).length;
    const close = (s.match(new RegExp('</' + tag + '>', 'g')) || []).length;
    if (open !== close) s = s.replace(new RegExp('</?' + tag + '>', 'g'), '');
  }
  return s;
}

// Telegram hard-caps messages at 4096 chars. Split at paragraph / line /
// word boundaries, falling back to a hard cut only if nothing else fits.
function splitForTelegram(text, maxLen) {
  if (text.length <= maxLen) return [text];
  const chunks = [];
  let remaining = text;
  while (remaining.length > maxLen) {
    let at = remaining.lastIndexOf('\n\n', maxLen);
    if (at < maxLen / 2) at = remaining.lastIndexOf('\n', maxLen);
    if (at < maxLen / 2) at = remaining.lastIndexOf(' ', maxLen);
    if (at < maxLen / 2) at = maxLen;
    chunks.push(remaining.slice(0, at).trimEnd());
    remaining = remaining.slice(at).trimStart();
  }
  if (remaining.length) chunks.push(remaining);
  return chunks;
}

const formatted = toTelegramHtml(answer);
const MAX = 3800;  // stay well under Telegram's 4096 limit to leave room for tag overhead
const chunks = splitForTelegram(formatted, MAX).map(balanceTags);

return chunks.map((chunk, i) => ({
  json: {
    ...norm,
    reply_text: chunk + (chunks.length > 1 ? `\n\n<i>(${i+1}/${chunks.length})</i>` : ''),
    reply_raw: answer,
    chunk_index: i,
    chunk_total: chunks.length,
  }
}));
